INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 40011, 321, "リリ", 24001, 125801, 2, 1, 0, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2, 40011, 322, "クリア", 24001, 126001, 2, 1, 0, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("んーと。\nこれ、あげる。\nはい", 3, 40011, 323, "プレシア", 24001, 126101, 2, 1, 0, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 4, 40011, 324, "リリ", 24001, 125801, 2, 1, 0, 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 5, 40011, 325, "クリア", 24001, 126001, 2, 1, 0, 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("お兄。\nきてくれて、うれしい", 6, 40011, 326, "プレシア", 24001, 126101, 2, 1, 0, 2);
